import{_ as n,a0 as l,w as p,s as i,ao as u,I as r,x as e,a1 as a,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"感谢开源和自由软件维护者的 10 种方法 | LCTT x X-CMD","titleTemplate":false,"description":"感谢开源和自由软件维护者的 10 种方法 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"感谢开源和自由软件维护者的 10 种方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"感谢开源和自由软件维护者的 10 种方法 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181121 10 ways to give thanks to open source and free software maintainers","title":"感谢开源和自由软件维护者的 10 种方法","tag":"201812","desc":""},"relativePath":"201812/20181121 10 ways to give thanks to open source and free software maintainers.md","filePath":"[post].md"}'),d={name:"201812/20181121 10 ways to give thanks to open source and free software maintainers.md"};function f(m,t,g,T,k,x){const s=l("Link");return p(),i("div",null,[t[18]||(t[18]=u('<h1 id="感谢开源和自由软件维护者的-10-种方法" tabindex="-1">感谢开源和自由软件维护者的 10 种方法 <a class="header-anchor" href="#感谢开源和自由软件维护者的-10-种方法" aria-label="Permalink to “感谢开源和自由软件维护者的 10 种方法”">​</a></h1><blockquote><p>如何表达你的感激之情。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/world_hands_diversity.png?itok=zm4EDxgE" alt=""></p><p>每天，我使用的那些高质量的软件 —— 开发和维护这些软件的人不需要我为之付款，他们尊重我的自由，并且慷慨地付出时间和精力。</p><p>在这个感恩的季节，我鼓励那些也使用和欣赏开源和自由软件维护者工作的人表达你的感激之情。以下是十种方法：</p><h3 id="容易做到的" tabindex="-1">容易做到的 <a class="header-anchor" href="#容易做到的" aria-label="Permalink to “容易做到的”">​</a></h3><p>1、发送电子邮件感谢开发人员。具体点说，告诉他们你使用他们的什么软件以及它是如何帮助了你。</p><p>2、使用你最喜爱的社交媒体平台宣传它。</p><p>3、写一篇关于你最喜欢的软件的博客文章。</p><h3 id="捐款" tabindex="-1">捐款 <a class="header-anchor" href="#捐款" aria-label="Permalink to “捐款”">​</a></h3><p>4、如果你最喜欢的开源项目接受捐款，请汇款。</p><p>5、如果你受雇于使用开源软件的公司，看你是否可以说服管理层赞助某些项目。</p><p>6、尽你所能地捐款。社交动机能做的不可思议！</p><h3 id="花费时间" tabindex="-1">花费时间 <a class="header-anchor" href="#花费时间" aria-label="Permalink to “花费时间”">​</a></h3><p>7、帮助审查补丁。</p><p>8、帮助分类 bug。</p>',16)),r("p",null,[t[1]||(t[1]=e("9、回答 IRC、邮件列表或 ",-1)),a(s,{href:"https://meta.stackoverflow.com/"},{default:o(()=>[...t[0]||(t[0]=[e("Stack Overflow",-1)])]),_:1}),t[2]||(t[2]=e(" 中的问题。",-1))]),t[19]||(t[19]=r("p",null,[r("strong",null,"10、额外的："),e("如果你像我一样，你在某个时候对开源社区的其他人说了一些严厉的话。承诺做得更好：用善良和开放沟通。感谢的最好方式是让开源社区成为人们能舒适沟通的地方。")],-1)),t[20]||(t[20]=r("hr",null,null,-1)),r("p",null,[t[4]||(t[4]=e("via: ",-1)),a(s,{href:"https://opensource.com/article/18/11/ways-give-thanks-open-source"},{default:o(()=>[...t[3]||(t[3]=[e("https://opensource.com/article/18/11/ways-give-thanks-open-source",-1)])]),_:1})]),r("p",null,[t[9]||(t[9]=e("作者：",-1)),a(s,{href:"https://opensource.com/users/moshez"},{default:o(()=>[...t[5]||(t[5]=[e("Moshe Zadka",-1)])]),_:1}),t[10]||(t[10]=e(" 选题：",-1)),a(s,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[6]||(t[6]=[e("lujun9972",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),a(s,{href:"https://github.com/geekpi"},{default:o(()=>[...t[7]||(t[7]=[e("geekpi",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[15]||(t[15]=e("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创编译，",-1)),a(s,{href:"https://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const h=n(d,[["render",f]]);export{b as __pageData,h as default};
